    n = int(data[0])
    words = sorted(data[1:1 + n], key=len)
    best = {}
    ans = 1
    for w in words:
        b = 1
        for i in range(len(w)):
            p = w[:i] + w[i + 1:]
            v = best.get(p)
            if v is not None and v + 1 > b:
                b = v + 1
        best[w] = b
        if b > ans:
            ans = b
    print(ans)

