import sys
from functools import lru_cache

data = sys.stdin.read().split()
n = int(data[0])
words = data[1:1 + n]
wset = set(words)
letters = 'abcdefghijklmnopqrstuvwxyz'

def successors(a):
    res = set()
    for i in range(len(a) + 1):
        for ch in letters:
            b = a[:i] + ch + a[i:]
            if b in wset:
                res.add(b)
    return res

@lru_cache(maxsize=None)
def longest(a):
    best = 1
    for b in successors(a):
        best = max(best, 1 + longest(b))
    return best

print(max(longest(w) for w in words))

